@classmethod
@lru_cache(1024 * 16)
def _split_cells(cls, segment: "Segment", cut: int) -> Tuple["Segment", "Segment"]:
    """Split a segment in to two at a given cell position.

    Note that splitting a double-width character, may result in that character turning
    into two spaces.

    Args:
        segment (Segment): A segment to split.
        cut (int): A cell position to cut on.

    Returns:
        A tuple of two segments.
    """
    text, style, control = segment
    _Segment = Segment
    cell_length = segment.cell_length
    if cut >= cell_length:
        return segment, _Segment("", style, control)

    pos = 0
    cell_pos = 0
    while pos < len(text):
        char = text[pos]
        char_cell_size = get_character_cell_size(char)

        if cell_pos + char_cell_size > cut:
            # The cut falls within this character. Split before it.
            break

        cell_pos += char_cell_size
        pos += 1

    before = text[:pos]
    after = text[pos:]

    padding_needed = cut - cell_pos

    if padding_needed > 0:
        # Pad the first segment to reach 'cut' cells.
        padded_text = before + (" " * padding_needed)
        return (
            _Segment(padded_text, style, control),
            _Segment(after, style, control),
        )
    else:
        # cell_pos == cut (or cell_pos > cut which shouldn't happen)
        return (
            _Segment(before, style, control),
            _Segment(after, style, control),
        )

